// What the host reads as a statement's parameters (host/memory.ts readParams) and writes as its rows (writeRows),
// against an oracle that does not share their fast paths: every text parameter must be what a fatal TextDecoder
// makes of a fresh copy of its bytes (a leading BOM kept: it is a character of the View; a decoder's default drops
// it, and until 23 November 2026 so did the host and this oracle), and refused exactly when that decoder refuses it. Inputs: 6,000 generated byte strings (ASCII of every length around the 64-byte fast path,
// with a byte of 128 or more at every place, broken UTF-8, a BOM), and memory that grows between two statements
// (a grow detaches the buffer the host's cached views were made over).
import '../node25.ts';
import { readParams, writeRows } from '../host/memory.ts';
import type { Mem, Query } from '../host/memory.ts';
import { finish, messageOf, ok, same } from './harness.ts';

function memOf(): Mem & { grow: (pages: number) => void } {
  const memory = new WebAssembly.Memory({ initial: 1, maximum: 64 });
  let top = 1024;
  const alloc = (n: number): number => {
    const at = top;
    top += (n + 7) & ~7;
    while (top > memory.buffer.byteLength) memory.grow(1);
    return at;
  };
  return {
    memory,
    alloc,
    grow: (pages: number) => {
      memory.grow(pages);
    },
  };
}
let seed = 20261122;
const rand = (n: number): number => {
  seed = (Math.imul(seed, 1103515245) + 12345) >>> 0;
  return (seed >>> 8) % n;
};
const oracle = new TextDecoder('utf-8', { fatal: true, ignoreBOM: true });
/** The text, or null when the decoder refuses the bytes. */
const expect = (b: Uint8Array): string | null => {
  try {
    return oracle.decode(Uint8Array.from(b));
  } catch {
    return null;
  }
};
/** One statement's parameter block: text kinds point at bytes written into memory, the rest are i64s. */
function write(m: Mem, kinds: string, values: (Uint8Array | bigint)[]): number {
  const ptr = m.alloc(16 * kinds.length);
  kinds.split('').forEach((k, i) => {
    const v = values[i];
    const d = new DataView(m.memory.buffer);
    if (k === 't' && v instanceof Uint8Array) {
      const at = m.alloc(v.length);
      new Uint8Array(m.memory.buffer, at, v.length).set(v);
      const d2 = new DataView(m.memory.buffer);
      d2.setUint32(ptr + 16 * i, at, true);
      d2.setUint32(ptr + 16 * i + 4, v.length, true);
    } else if (typeof v === 'bigint') d.setBigInt64(ptr + 16 * i, v, true);
  });
  return ptr;
}
const q = (params: string): Query => ({ sql: 'SELECT 1', params, row: null, columns: null });
const read = (m: Mem, kinds: string, ptr: number): unknown[] | 'refused' => {
  try {
    return readParams(m, q(kinds), ptr);
  } catch (e) {
    if (e instanceof TypeError || e instanceof RangeError) return 'refused';
    throw e;
  }
};

function bytesCase(): Uint8Array {
  const n = rand(5) === 0 ? rand(200) : 56 + rand(16); // around the 64-byte edge most of the time
  const b = Uint8Array.from({ length: n }, () => 32 + rand(95));
  const kind = rand(6);
  if (kind === 1 && n > 0) b[rand(n)] = 128 + rand(128); // one high byte, anywhere: usually broken UTF-8
  if (kind === 2 && n > 1) b.set([0xc3, 0xa9], rand(n - 1)); // é, well formed
  if (kind === 3 && n > 2) b.set([0xef, 0xbb, 0xbf], 0); // a BOM, which the decoder drops
  if (kind === 4 && n > 3) b.set([0xf0, 0x9f, 0x98, 0x80], rand(n - 3)); // an astral character
  if (kind === 5 && n > 0) b[rand(n)] = rand(32); // a control byte, which is ASCII
  return b;
}

let agree = 0;
const m = memOf();
for (let k = 0; k < 6000; k++) {
  const a = bytesCase();
  const b = bytesCase();
  const ptr = write(m, 'tit', [a, BigInt(rand(1 << 30)) - 5n, b]);
  const got = read(m, 'tit', ptr);
  const x = expect(a);
  const y = expect(b);
  const want = x === null || y === null ? 'refused' : [x, null, y];
  const fine = got === 'refused' ? want === 'refused' : want !== 'refused' && got[0] === x && got[2] === y;
  if (fine) agree++;
  else if (agree >= 0) {
    ok(`params #${k}`, false, `got ${JSON.stringify(got)}, wanted ${JSON.stringify(want)}`);
    agree = -1e9;
  }
  if (k % 500 === 499) m.grow(1); // the buffer the cached views were made over is detached now
}
same('6,000 parameter blocks read as the fatal TextDecoder reads them', agree, 6000);

// an Option (an upper-case kind): the i32 at 8 is 1 for Some and 0 for None, which is NULL, whatever the value
// cells hold (compiler/gen/sql.ts bindParams)
{
  const kinds = 'TITIF';
  const ptr = m.alloc(16 * kinds.length);
  const d = new DataView(m.memory.buffer);
  const at = m.alloc(5);
  new Uint8Array(m.memory.buffer, at, 5).set(new TextEncoder().encode('north'));
  d.setUint32(ptr, at, true);
  d.setUint32(ptr + 4, 5, true);
  d.setInt32(ptr + 8, 1, true);
  d.setBigInt64(ptr + 16, 42n, true);
  d.setInt32(ptr + 24, 1, true);
  d.setUint32(ptr + 32, at, true); // a None's value cells are left as they were: not read
  d.setUint32(ptr + 36, 5, true);
  d.setInt32(ptr + 40, 0, true);
  d.setBigInt64(ptr + 48, 7n, true);
  d.setInt32(ptr + 56, 0, true);
  d.setFloat64(ptr + 64, 2.5, true);
  d.setInt32(ptr + 72, 1, true);
  same('Options: Some is its value, None is NULL', read(m, kinds, ptr), ['north', 42, null, null, 2.5]);
}

// integers: exact within ±2^53, refused outside
{
  const mm = memOf();
  for (const v of [0n, 1n, -1n, 2n ** 53n - 1n, -(2n ** 53n) + 1n, 2n ** 32n, -(2n ** 32n), 4294967295n])
    same(`Int ${v}`, readParams(mm, q('i'), write(mm, 'i', [v])), [Number(v)]);
  for (const v of [2n ** 53n, -(2n ** 53n), 2n ** 63n - 1n])
    same(`Int ${v} is refused`, read(mm, 'i', write(mm, 'i', [v])), 'refused');
}

// text that points past the end of memory is refused, short or long, not read as what lies there
{
  const mm = memOf();
  const ptr = mm.alloc(16);
  const d = new DataView(mm.memory.buffer);
  for (const n of [3, 200]) {
    d.setUint32(ptr, mm.memory.buffer.byteLength - 1, true);
    d.setUint32(ptr + 4, n, true);
    same(`text of ${n} bytes past the end is refused`, read(mm, 't', ptr), 'refused');
  }
}

// rows: written after memory grows, and a wrong cell names its own column
{
  const mm = memOf();
  const rq: Query = { sql: 'SELECT a, b, c FROM t', params: '', row: 'tiT', columns: ['a', 'b', 'c'] };
  mm.grow(2);
  const rows = Array.from({ length: 3000 }, (_, i) => [`k${i}é`, i, i % 2 ? null : 'x']);
  const at = writeRows(mm, rq, rows);
  const d = new DataView(mm.memory.buffer);
  const u = new Uint8Array(mm.memory.buffer);
  let o = at + 8;
  const back: unknown[][] = [];
  for (let r = 0; r < d.getUint32(at, true); r++) {
    const n = d.getUint32(o, true);
    const a = new TextDecoder().decode(u.subarray(o + 4, o + 4 + n));
    o += 4 + n;
    const b = Number(d.getBigInt64(o, true));
    o += 8;
    const has = d.getBigInt64(o, true) === 1n;
    o += 8;
    let c: string | null = null;
    if (has) {
      const cn = d.getUint32(o, true);
      c = new TextDecoder().decode(u.subarray(o + 4, o + 4 + cn));
      o += 4 + cn;
    }
    back.push([a, b, c]);
  }
  same('3,000 rows read back as written', back, rows);
  let why = '';
  try {
    writeRows(mm, rq, [
      ['a', 1, 'x'],
      ['b', 'two', 'y'],
    ]);
  } catch (e) {
    why = messageOf(e);
  }
  same('a wrong cell names its column', why, 'sql: column b should be an integer but is text: SELECT a, b, c FROM t');
}

finish();
